/* Tests against spec/test_vectors.json (through test_vectors.h, generated by tools/generate_tables.py). */
#include <stdio.h>
#include <string.h>

#include "jlspp_chauvet_spot260x.h"
#include "jlspp_dmx.h"
#include "jlspp_mindi_spider.h"
#include "test_vectors.h"

static int failures = 0;

/* Prints one result line and counts the failures. */
static void check(int ok, const char *test, const char *what)
{
    printf("%s  %-36s %s\n", ok ? "OK    " : "FAILED", test, what);
    if (!ok) {
        failures++;
    }
}

/* Universe of the test vector called `name`, or NULL. */
static const uint8_t *vector_universe(const char *name)
{
    int i;
    for (i = 0; i < JLSPP_TEST_VECTOR_COUNT; i++) {
        if (strcmp(JLSPP_TEST_VECTORS[i].name, name) == 0) {
            return JLSPP_TEST_VECTORS[i].universe;
        }
    }
    return NULL;
}

static int universe_equals_vector(const uint8_t *universe, const char *name)
{
    const uint8_t *expected = vector_universe(name);
    return expected != NULL && memcmp(universe, expected, JLSPP_UNIVERSE_SIZE) == 0;
}

/* ----------------------------------------------------------------------------- frames */

static void test_frames(void)
{
    uint8_t frame[JLSPP_FRAME_LEN];
    uint8_t universe[JLSPP_UNIVERSE_SIZE];
    uint8_t code = 0;
    int i;

    for (i = 0; i < JLSPP_TEST_VECTOR_COUNT; i++) {
        const jlspp_test_vector *v = &JLSPP_TEST_VECTORS[i];

        jlspp_build_frame(v->universe, v->code_num, 0, 0, frame);
        check(memcmp(frame, v->frame, JLSPP_FRAME_LEN) == 0, v->name, "build_frame == vector");

        check(jlspp_decode_frame(v->frame, universe, &code) == JLSPP_OK
                  && memcmp(universe, v->universe, JLSPP_UNIVERSE_SIZE) == 0
                  && code == v->code_num,
              v->name, "decode_frame == universe");
    }

    frame[1] = 'X';
    check(jlspp_decode_frame(frame, universe, NULL) == JLSPP_ERROR, "is_frame", "invalid frame rejected");
}

/* ------------------------------------------------------------------------------ Spider */

static void test_spider(void)
{
    uint8_t universe[JLSPP_UNIVERSE_SIZE] = {0};
    jlspp_spider spider;

    check(jlspp_spider_init(&spider, 1) == JLSPP_OK, "spider", "init at address 1");
    check(jlspp_spider_dmx_channel(&spider, JLSPP_SPIDER_MOTOR_1) == 2, "spider", "address quirk shifts by one");

    jlspp_spider_set_wings(&spider, universe, 200, 1);
    jlspp_spider_set_dimmer(&spider, universe, 255);
    jlspp_spider_set_led(&spider, universe, 1, 255);
    jlspp_spider_set_led(&spider, universe, 5, 255);
    check(universe_equals_vector(universe, "mindi_spider_address1_code7"), "spider", "helpers == vector");

    check(jlspp_spider_set_led(&spider, universe, 9, 255) == JLSPP_ERROR, "spider", "LED 9 rejected");
}

/* -------------------------------------------------------------------------- Spot 260X */

static void test_spot260x(void)
{
    uint8_t universe[JLSPP_UNIVERSE_SIZE] = {0};
    jlspp_spot260x head1, head2, small;

    jlspp_spot260x_init(&head1, 17, JLSPP_SPOT260X_MODE_14CH);
    jlspp_spot260x_set_pan(&head1, universe, 0x8000);
    jlspp_spot260x_set_tilt(&head1, universe, 0x4000);
    jlspp_spot260x_set_color(&head1, universe, JLSPP_SPOT260X_RED);
    jlspp_spot260x_set_gobo(&head1, universe, JLSPP_SPOT260X_GOBO_3);
    jlspp_spot260x_set_gobo_rotation(&head1, universe, JLSPP_SPOT260X_ROTATION_CLOCKWISE, 128);
    jlspp_spot260x_set_prism(&head1, universe, 1);
    jlspp_spot260x_set_focus(&head1, universe, 128);
    jlspp_spot260x_light_on(&head1, universe, 255);

    jlspp_spot260x_init(&head2, 31, JLSPP_SPOT260X_MODE_14CH);
    jlspp_spot260x_set_pan(&head2, universe, 0x8000);
    jlspp_spot260x_set_tilt(&head2, universe, 0x4000);
    jlspp_spot260x_set_color(&head2, universe, JLSPP_SPOT260X_BLUE);
    jlspp_spot260x_set_gobo(&head2, universe, JLSPP_SPOT260X_GOBO_OPEN);
    jlspp_spot260x_set_focus(&head2, universe, 128);
    jlspp_spot260x_set_dimmer(&head2, universe, 255);
    jlspp_spot260x_set_strobe(&head2, universe, 128, JLSPP_SPOT260X_STROBE_NORMAL);

    check(universe_equals_vector(universe, "chauvet_spot260x_two_heads_code9"), "spot260x", "helpers == vector");

    /* 8-channel mode: no dimmer, shutter on channel 8, no fine pan */
    jlspp_spot260x_init(&small, 1, JLSPP_SPOT260X_MODE_8CH);
    check(!jlspp_spot260x_has(&small, JLSPP_SPOT260X_DIMMER), "spot260x 8ch", "no dimmer");
    check(jlspp_spot260x_dmx_channel(&small, JLSPP_SPOT260X_SHUTTER) == 8, "spot260x 8ch", "shutter on channel 8");
    check(jlspp_spot260x_set_dimmer(&small, universe, 255) == JLSPP_ERROR, "spot260x 8ch", "set_dimmer refused");

    /* speed scaling at the ends of the ranges */
    memset(universe, 0, sizeof universe);
    jlspp_spot260x_set_strobe(&head1, universe, 255, JLSPP_SPOT260X_STROBE_RANDOM);
    check(universe[jlspp_spot260x_dmx_channel(&head1, JLSPP_SPOT260X_SHUTTER) - 1] == 215,
          "spot260x", "fastest random strobe = 215");
    jlspp_spot260x_set_color_rainbow(&head1, universe, 255, 0);
    check(universe[jlspp_spot260x_dmx_channel(&head1, JLSPP_SPOT260X_COLOR_WHEEL) - 1] == 190,
          "spot260x", "fastest rainbow = 190");
    jlspp_spot260x_set_movement_macro(&head1, universe, 8, 1);
    check(universe[jlspp_spot260x_dmx_channel(&head1, JLSPP_SPOT260X_MOVEMENT_MACRO) - 1] == 251,
          "spot260x", "sound macro 8 = 251");

    check(jlspp_spot260x_init(&small, 500, JLSPP_SPOT260X_MODE_14CH) == JLSPP_ERROR,
          "spot260x", "address 500 refused in 14ch");
}

int main(void)
{
    test_frames();
    test_spider();
    test_spot260x();

    printf("\n%s (%d failure(s))\n", failures == 0 ? "ALL TESTS PASS" : "SOME TESTS FAIL", failures);
    return failures == 0 ? 0 : 1;
}
